const scholarships=[
 {id:'women-tech',title:'Women in Technology Scholarship',sponsor:'Palantir',mark:'PT',amount:10000,days:18,match:98,tone:'#d9ff5b',tags:['STEM','Leadership','Women'],summary:'For students advancing representation and impact in technical fields.',reasons:['Your Computer Science major is a direct field match','Your 3.8 GPA exceeds the 3.0 requirement','First-generation status strengthens your story']},
 {id:'future-builders',title:'Future Builders Grant',sponsor:'Generation Google',mark:'GG',amount:10000,days:27,match:94,tone:'#9ce0cd',tags:['Computer Science','Need-based'],summary:'Supports students using technology to improve their communities.',reasons:['Your major matches the program focus','Michigan residents are eligible','Community impact is weighted highly']},
 {id:'green-code',title:'Green Code Fellowship',sponsor:'Climate Futures Lab',mark:'CF',amount:7500,days:42,match:91,tone:'#b6d883',tags:['Technology','Climate','Essay'],summary:'For builders applying software to urgent environmental challenges.',reasons:['Technical coursework aligns with the fellowship','No citizenship restriction','Your academic standing is competitive']},
 {id:'first-forward',title:'First Forward Scholars Award',sponsor:'Ascend Foundation',mark:'AF',amount:12500,days:55,match:89,tone:'#ffb86b',tags:['First-gen','Leadership'],summary:'Recognizes first-generation students creating momentum for others.',reasons:['First-generation status is a core requirement','Your GPA is above the preferred range','Open to undergraduate students']},
 {id:'michigan-stem',title:'Michigan STEM Promise',sponsor:'Great Lakes Education Fund',mark:'GL',amount:5000,days:63,match:87,tone:'#93b7ff',tags:['Michigan','STEM'],summary:'A statewide award keeping Michigan STEM talent close to home.',reasons:['Michigan residency is required','Computer Science qualifies as STEM','Current enrollment status matches']},
 {id:'digital-equity',title:'Digital Equity Changemaker',sponsor:'Mozilla Foundation',mark:'MF',amount:8000,days:76,match:84,tone:'#c9a6ff',tags:['Open web','Community'],summary:'Backs students working toward a safer, more inclusive internet.',reasons:['Technology field is preferred','Leadership potential matches','Open to all U.S. undergraduates']},
 {id:'cyber-future',title:'Secure Futures Scholarship',sponsor:'CyberCorps Alliance',mark:'SC',amount:6000,days:90,match:82,tone:'#ff9d88',tags:['Cybersecurity','STEM'],summary:'Supports the next generation of responsible security practitioners.',reasons:['Computer Science is an eligible major','Your GPA clears the threshold','Essay topic fits technical experience']},
 {id:'open-source',title:'Open Source Student Grant',sponsor:'Code Commons',mark:'CC',amount:3500,days:110,match:79,tone:'#80d2df',tags:['Open source','Portfolio'],summary:'Microgrant for students who contribute code to public-interest projects.',reasons:['Technical portfolio can demonstrate fit','All undergraduate years accepted','Project-based selection favors builders']}
];
const state={saved:JSON.parse(localStorage.getItem('ss-saved')||'[]'),statuses:JSON.parse(localStorage.getItem('ss-statuses')||'{}'),profile:JSON.parse(localStorage.getItem('ss-profile')||'null')||{major:'Computer Science',gpa:'3.8',state:'Michigan',year:'Undergraduate',firstGen:true},best:true};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n)}
function deadline(days){const d=new Date();d.setDate(d.getDate()+days);return d}
function dateLabel(days){return deadline(days).toLocaleDateString('en-US',{month:'short',day:'numeric'})}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2400)}
function render(){
 const q=$('#search').value.toLowerCase(),min=+$ ('#amount-filter').value,maxDays=+$ ('#deadline-filter').value;
 const visible=scholarships.filter(s=>(s.title+' '+s.sponsor+' '+s.tags.join(' ')).toLowerCase().includes(q)&&s.amount>=min&&s.days<=maxDays).sort((a,b)=>state.best?b.match-a.match:a.days-b.days);
 $('#result-count').textContent=visible.length;$('#potential-total').textContent=money(visible.reduce((n,s)=>n+s.amount,0));
 $('#scholarship-list').innerHTML=visible.map(s=>`<article class="scholarship-card" data-id="${s.id}"><div><div class="card-top"><span class="sponsor-mark" style="--tone:${s.tone}">${s.mark}</span><div><h3>${s.title}</h3><small>${s.sponsor}</small></div></div><p>${s.summary}</p><div class="tags">${s.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></div><div class="award"><strong>${money(s.amount)}</strong><span class="match">${s.match}% MATCH</span><span class="deadline">${s.days} days left</span><button class="save-button ${state.saved.includes(s.id)?'saved':''}" data-save="${s.id}" aria-label="${state.saved.includes(s.id)?'Remove from':'Save to'} tracker">${state.saved.includes(s.id)?'★':'☆'}</button></div></article>`).join('');
 $('#empty-state').hidden=visible.length>0;
 $('#deadline-list').innerHTML=scholarships.slice(0,3).map(s=>`<div class="deadline-item"><span class="date-box">${deadline(s.days).toLocaleString('en-US',{month:'short'}).toUpperCase()}<b>${deadline(s.days).getDate()}</b></span><div><strong>${s.title}</strong><p>${s.days} days · ${money(s.amount)}</p></div></div>`).join('');
 updateSaved();
}
function updateSaved(){
 $('#saved-count').textContent=state.saved.length;$('#stat-saved').textContent=state.saved.length;
 const selected=scholarships.filter(s=>state.saved.includes(s.id));$('#stat-value').textContent=money(selected.reduce((n,s)=>n+s.amount,0));
 $('#stat-progress').textContent=selected.filter(s=>(state.statuses[s.id]||'saved')==='progress').length;
 $('#stat-next').textContent=selected.length?dateLabel(Math.min(...selected.map(s=>s.days))):'—';
 const cols=[['saved','Saved'],['progress','In progress'],['submitted','Submitted']];
 $('#kanban').innerHTML=cols.map(([key,label])=>`<section class="kanban-column"><div class="kanban-title"><span>${label}</span><span>${selected.filter(s=>(state.statuses[s.id]||'saved')===key).length}</span></div>${selected.filter(s=>(state.statuses[s.id]||'saved')===key).map(s=>`<article class="kanban-card"><h3>${s.title}</h3><p>${money(s.amount)} · due ${dateLabel(s.days)}</p><select data-status="${s.id}" aria-label="Update ${s.title} status"><option value="saved" ${key==='saved'?'selected':''}>Saved</option><option value="progress" ${key==='progress'?'selected':''}>In progress</option><option value="submitted" ${key==='submitted'?'selected':''}>Submitted</option></select></article>`).join('')||'<p class="eyebrow">Nothing here yet</p>'}</section>`).join('');
 localStorage.setItem('ss-saved',JSON.stringify(state.saved));localStorage.setItem('ss-statuses',JSON.stringify(state.statuses));
}
function toggleSave(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];render();toast(state.saved.includes(id)?'Saved to your application tracker':'Removed from tracker')}
function showDetail(id){const s=scholarships.find(x=>x.id===id);$('#detail-content').innerHTML=`<button class="icon-button detail-close" aria-label="Close">×</button><p class="eyebrow">${s.sponsor} · ${money(s.amount)}</p><h2>${s.title}</h2><strong class="detail-score">${s.match}% match</strong><p>${s.summary}</p><div class="detail-reasons"><b>Why this fits you</b><ul>${s.reasons.map(r=>`<li>${r}</li>`).join('')}</ul></div><p class="deadline">Deadline: ${dateLabel(s.days)} · ${s.days} days remaining</p><div class="detail-actions"><button data-save="${s.id}">${state.saved.includes(s.id)?'Remove from tracker':'Save application'}</button><a href="#" data-demo-apply>Review requirements ↗</a></div>`;$('#detail-dialog').showModal()}
function switchView(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===view+'-view'));$$('.nav-link').forEach(v=>v.classList.toggle('active',v.dataset.view===view));if(view==='tracker')updateSaved();scrollTo(0,0)}
function registerAgentTools(){
 const context=document.modelContext;if(!context?.registerTool)return;
 const report=e=>console.warn('WebMCP tool registration failed',e);
 try{void Promise.resolve(context.registerTool({name:'search_scholarships',title:'Search scholarships',description:'Search and rank the scholarship catalog by keywords, minimum award, and maximum days until deadline.',inputSchema:{type:'object',properties:{query:{type:'string'},minimumAward:{type:'number',minimum:0},maximumDays:{type:'number',minimum:1}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input={}){if(typeof input.query!=='undefined'&&typeof input.query!=='string')throw new Error('query must be a string');if(typeof input.minimumAward!=='undefined'&&(!Number.isFinite(input.minimumAward)||input.minimumAward<0))throw new Error('minimumAward must be a non-negative number');if(typeof input.maximumDays!=='undefined'&&(!Number.isFinite(input.maximumDays)||input.maximumDays<1))throw new Error('maximumDays must be a positive number');const q=(input.query||'').toLowerCase(),min=input.minimumAward||0,max=input.maximumDays||365;const matches=scholarships.filter(s=>(s.title+' '+s.sponsor+' '+s.tags.join(' ')).toLowerCase().includes(q)&&s.amount>=min&&s.days<=max).sort((a,b)=>b.match-a.match).map(({id,title,sponsor,amount,days,match})=>({id,title,sponsor,amount,daysUntilDeadline:days,matchPercent:match}));return{count:matches.length,matches}}})).catch(report)}catch(e){report(e)}
 try{void Promise.resolve(context.registerTool({name:'save_scholarship',title:'Save scholarship',description:'Save one catalog scholarship to the visible application tracker.',inputSchema:{type:'object',properties:{scholarshipId:{type:'string'}},required:['scholarshipId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const item=scholarships.find(s=>s.id===input?.scholarshipId);if(!item)throw new Error('Unknown scholarshipId');if(!state.saved.includes(item.id)){state.saved.push(item.id);render()}return{saved:true,scholarshipId:item.id,title:item.title,trackerCount:state.saved.length}}})).catch(reportError)}catch(e){report(e)}
}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){e.stopPropagation();toggleSave(save.dataset.save);if($('#detail-dialog').open)$('#detail-dialog').close();return}const card=e.target.closest('.scholarship-card');if(card)showDetail(card.dataset.id);const view=e.target.closest('[data-view]');if(view)switchView(view.dataset.view);if(e.target.matches('.detail-close'))$('#detail-dialog').close();if(e.target.closest('[data-demo-apply]')){e.preventDefault();toast('Requirements checklist generated')};});
$$('#search,#amount-filter,#deadline-filter').forEach(el=>el.addEventListener('input',render));
$('#best-match').addEventListener('click',()=>{state.best=!state.best;$('#best-match').textContent=state.best?'✦ Best matches':'◷ Soonest first';render()});
$('#reset-filters').addEventListener('click',()=>{$('#search').value='';$('#amount-filter').value='0';$('#deadline-filter').value='365';render()});
$('#profile-dialog').addEventListener('close',()=>{if($('#profile-dialog').returnValue!=='save')return;const data=Object.fromEntries(new FormData($('#profile-form')));data.firstGen=!!data.firstGen;state.profile=data;localStorage.setItem('ss-profile',JSON.stringify(data));applyProfile();toast('Matches recalculated around your profile')});
function openProfile(){$('#profile-form').elements.major.value=state.profile.major;$('#profile-form').elements.gpa.value=state.profile.gpa;$('#profile-form').elements.state.value=state.profile.state;$('#profile-form').elements.year.value=state.profile.year;$('#profile-form').elements.firstGen.checked=state.profile.firstGen;$('#profile-dialog').showModal()}
['#edit-profile','#profile-pencil','#strengthen-profile'].forEach(id=>$(id).addEventListener('click',openProfile));
function applyProfile(){$('#profile-major').textContent=state.profile.major;$('#profile-gpa').textContent=state.profile.gpa;$('#profile-state').textContent=state.profile.state;$('#profile-year').textContent=state.profile.year}
$('#export-results').addEventListener('click',()=>{const rows=['Scholarship,Sponsor,Award,Match,Deadline',...scholarships.map(s=>`"${s.title}","${s.sponsor}",${s.amount},${s.match}%,${dateLabel(s.days)}`)];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));a.download='scholarsprint-matches.csv';a.click();URL.revokeObjectURL(a.href);toast('Match report exported')});
$('#calendar-export').addEventListener('click',()=>{const events=scholarships.slice(0,3).map(s=>{const d=deadline(s.days).toISOString().slice(0,10).replaceAll('-','');return`BEGIN:VEVENT\nDTSTART;VALUE=DATE:${d}\nSUMMARY:${s.title} deadline\nDESCRIPTION:${money(s.amount)} scholarship via ScholarSprint\nEND:VEVENT`}).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([`BEGIN:VCALENDAR\nVERSION:2.0\n${events}\nEND:VCALENDAR`],{type:'text/calendar'}));a.download='scholarship-deadlines.ics';a.click();URL.revokeObjectURL(a.href);toast('Calendar file ready')});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();switchView('discover');$('#search').focus()};if(e.key==='Escape'&&$('#detail-dialog').open)$('#detail-dialog').close()});
$('#kanban').addEventListener('change',e=>{if(e.target.dataset.status){state.statuses[e.target.dataset.status]=e.target.value;updateSaved();toast('Application stage updated')}});
$$('.radar-blip').forEach(b=>b.addEventListener('click',()=>showDetail(b.dataset.target)));
applyProfile();render();registerAgentTools();
